const html = $input.first().json.html || "";

const matches = [...html.matchAll(
  /href\s*=\s*["']([^"']+)["']/gi
)];

const detailUrls = [...new Set(
  matches.map(m => m[1]).filter(url =>
    /^https:\/\/jdih\.kpu\.go\.id\/(peraturan-kpu|keputusan-kpu)\/detail\//i.test(url)
  )
)];

return detailUrls.map(detail_url => ({
  json: { detail_url, source: "JDIH KPU" }
}));

const results = [];
// Hanya dokumen yang statusnya BERLAKU dan terbit tahun 2024-2026 yang diproses.
const TAHUN_MIN = 2024, TAHUN_MAX = 2026;
function docYear(title, pdfUrl) {
  const t = String(title || '').match(/Tahun\s+((?:19|20)\d{2})/i);
  if (t) return Number(t[1]);
  const f = decodeURIComponent(String(pdfUrl).split(/[?#]/)[0].split('/').pop() || '').match(/((?:19|20)\d{2})\s*_?(?:pkpu|kpt|kep)/i);
  return f ? Number(f[1]) : null;
}
const seen = new Set();

// Status keberlakuan dan judul dibaca dari halaman detail JDIH.
// Jika tidak terbaca, status = belum_diverifikasi (chatbot memberi catatan).
const plain = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

function legalStatus(html) {
  const m = plain(html).match(/status(?:\s+(?:peraturan|dokumen|hukum))?\s*:?\s*(tidak\s+berlaku|dicabut|berlaku|diubah)/i);
  if (!m) return 'belum_diverifikasi';
  const v = m[1].toLowerCase().replace(/\s+/g, ' ');
  if (v === 'berlaku') return 'berlaku';
  if (v === 'diubah') return 'belum_diverifikasi';
  return 'tidak_berlaku';
}

function pageTitle(html) {
  // Halaman detail JDIH menulis judul lengkap sebelum label "Tipe Dokumen :".
  const full = plain(html).match(/((?:Peraturan|Keputusan) Komisi Pemilihan Umum Nomor \d+ Tahun \d{4} tentang .+?)\s+Tipe Dokumen\s*:/i);
  if (full) return full[1].trim().slice(0, 500);
  const candidates = [
    (html.match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i) || [])[1],
    (html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || [])[1],
    (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1],
  ].map(plain).filter((t) => t.length >= 10 && !/^JDIH\b/i.test(t));
  return candidates.length ? candidates[0].slice(0, 500) : null;
}

for (const item of $input.all()) {
  const html = item.json.html || "";
  const title = pageTitle(html);
  const legal_status = legalStatus(html);

  const matches = [...html.matchAll(
    /(?:href|src)\s*=\s*["']([^"']+\.pdf(?:\?[^"']*)?)["']/gi
  )];

  for (const match of matches) {
    let pdf_url = match[1].replace(/&amp;/g, "&");

    if (pdf_url.startsWith("//")) {
      pdf_url = "https:" + pdf_url;
    } else if (pdf_url.startsWith("/")) {
      pdf_url = "https://jdih.kpu.go.id" + pdf_url;
    } else if (!/^https?:\/\//i.test(pdf_url)) {
      pdf_url = "https://jdih.kpu.go.id/" + pdf_url;
    }

    if (!pdf_url.startsWith("https://jdih.kpu.go.id/")) {
      continue;
    }

    const isPkpu = pdf_url.includes("/data/data_pkpu/");
    const isSubang = pdf_url.includes("/data-kabko/subang/data_kepkpud/");
    if (!isPkpu && !isSubang) {
      continue;
    }

    // Versi terjemahan bahasa Inggris tidak diindeks (isi sama, bahasa berbeda).
    if (/_english\.pdf$/i.test(pdf_url)) continue;

    if (seen.has(pdf_url)) continue;
    if (legal_status !== 'berlaku') continue;            // tidak berlaku / belum jelas: lewati
    const year = docYear(title, pdf_url);
    if (!year || year < TAHUN_MIN || year > TAHUN_MAX) continue;
    seen.add(pdf_url);

    if (isSubang) {
      // Keputusan KPU Kabupaten Subang: hanya yang Berlaku, tahun 2024 ke atas.
      const t = plain(html).match(/(Keputusan Komisi Pemilihan Umum Kabupaten Subang Nomor .+?)\s+Tipe\s*:/i);
      const subangTitle = t ? t[1].trim().slice(0, 500) : null;
      const ny = (subangTitle || '').match(/Nomor\s+(.+?)\s+Tahun\s+(\d{4})/i);
      const subangYear = ny ? Number(ny[2]) : year;
      if (legal_status !== 'berlaku' || !subangYear || subangYear < 2024 || subangYear > 2026) continue;
      results.push({ json: { pdf_url, source: "JDIH KPU Kabupaten Subang",
        document_type: "Keputusan KPU Kabupaten Subang", title: subangTitle,
        document_number: ny ? ny[1].trim().slice(0, 120) : null, year: subangYear, legal_status,
        detail_url: item.json.detail_url ?? null } });
      continue;
    }

    results.push({
      json: {
        pdf_url,
        source: "JDIH KPU",
        document_type: "PKPU",
        title,
        legal_status,
        year,
        detail_url: item.json.detail_url ?? null,
      }
    });
  }
}

return results;

// Input dari webhook: manual ingest ({ pdf_url, title?, ... }) atau Retry dari dashboard admin ({ error_id, ... }).
const body = $input.first().json.body ?? {};
const pick = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const pdfUrl = pick(body.pdf_url);
if (pdfUrl && !/^https:\/\/[^\s]+$/i.test(pdfUrl)) {
  throw new Error('pdf_url harus berupa URL https.');
}
const yearNum = Number(body.year);
return [{
  json: {
    pdf_url: pdfUrl,
    retry_error_id: pick(body.retry_error_id) ?? pick(body.error_id),
    source: pick(body.source) ?? (pdfUrl ? 'Webhook' : 'Retry Admin'),
    document_type: pick(body.document_type),
    document_number: pick(body.document_number),
    title: pick(body.title),
    legal_status: pick(body.legal_status),
    year: Number.isInteger(yearNum) && yearNum >= 1800 && yearNum <= 2200 ? yearNum : null,
  },
}];

// Menyatukan jalur webhook dan jadwal harian sebelum download PDF.
let retryErrorId = null;
try {
  if ($('Normalisasi Input Webhook').isExecuted) {
    retryErrorId = $('Normalisasi Input Webhook').first().json.retry_error_id ?? null;
  }
} catch (e) { /* eksekusi dari jadwal */ }

return $input.all().map((item, index) => {
  let detail = {};
  try { detail = $('Periksa Link Download').itemMatching(index).json; } catch (e) {
    try { detail = $('Normalisasi Input Webhook').first().json; } catch (e2) { /* tidak ada metadata */ }
  }
  const { already_processed, ...rest } = item.json;
  const j = { ...detail, ...Object.fromEntries(Object.entries(rest).filter(([, v]) => v !== null && v !== undefined)) };
  const url = String(j.pdf_url);
  let fileName = '';
  // `URL` tidak tersedia di sandbox Code node n8n; ambil nama file dengan string biasa.
  try { fileName = decodeURIComponent(url.split(/[?#]/)[0].split('/').pop() || ''); } catch (e) { fileName = url.split('/').pop() || ''; }
  const base = fileName.replace(/\.pdf$/i, '').replace(/[_+]+/g, ' ').replace(/\s+/g, ' ').trim();
  const fromTitle = String(j.title || '').match(/Nomor\s+(\d+)\s+Tahun\s+(\d{4})/i);
  // Keputusan KPU Kabupaten Subang: nama file 2026kpt3213009 (3213 = kode Subang) atau 2024kpt1862.
  const subangUrl = url.includes('/data-kabko/subang/');
  const subangFile = base.match(/((?:19|20)\d{2})kpt(?:3213)?0*(\d+)/i);
  if (subangUrl && subangFile && !j.title) {
    j.document_type = j.document_type ?? 'Keputusan KPU Kabupaten Subang';
    j.source = j.source ?? 'JDIH KPU Kabupaten Subang';
    j.document_number = j.document_number ?? subangFile[2];
    j.year = j.year ?? Number(subangFile[1]);
    j.title = `Keputusan KPU Kabupaten Subang Nomor ${subangFile[2]} Tahun ${subangFile[1]}`;
  }
  // Produk hukum Pemkab Subang (perda/perbup, mis. Pilkades e-voting) dari JDIH Kabupaten Subang.
  if (/^https:\/\/jdih\.subang\.go\.id\//i.test(url)) {
    const t = String(j.title || '');
    j.document_type = j.document_type ?? (/peraturan daerah|\bperda\b/i.test(t) ? 'Peraturan Daerah Kabupaten Subang' : 'Peraturan Bupati Subang');
    j.source = (j.source && j.source !== 'Webhook') ? j.source : 'JDIH Kabupaten Subang';
    const nt = t.match(/Nomor\s+(\d+)\s+Tahun\s+(\d{4})/i);
    if (nt) { j.document_number = j.document_number ?? nt[1]; j.year = j.year ?? Number(nt[2]); }
  }
  const fromFile = base.match(/((?:19|20)\d{2})\s*(?:pkpu|kpt|kep)\s*0*(\d+)/i);
  const yearMatch = fromTitle ? [fromTitle[2]] : (fromFile ? [fromFile[1]] : base.match(/(?:19|20)\d{2}/));
  const numberMatch = fromTitle ? [null, fromTitle[1]] : (fromFile ? [null, fromFile[2]] : base.match(/(?:nomor|no\.?)\s*(\d+)/i));
  return {
    json: {
      pdf_url: url,
      source: j.source ?? 'JDIH KPU',
      document_type: j.document_type ?? 'PKPU',
      title: j.title ?? (numberMatch && yearMatch
        ? `Peraturan KPU Nomor ${numberMatch[1]} Tahun ${yearMatch[0]}`
        : (base ? base.slice(0, 2000) : null)),
      document_number: j.document_number ?? (numberMatch ? numberMatch[1] : null),
      year: j.year ?? (yearMatch ? Number(yearMatch[0]) : null),
      legal_status: ['berlaku', 'tidak_berlaku'].includes(j.legal_status) ? j.legal_status : 'belum_diverifikasi',
      retry_error_id: j.retry_error_id ?? retryErrorId,
    },
    pairedItem: { item: index },
  };
});

// Output Pinecone (mode insert) = satu item per chunk yang berhasil di-upsert.
// Status sukses hanya dikirim dari sini, yaitu setelah Pinecone menerima upsert.
const groups = new Map();
$input.all().forEach((item, i) => {
  const meta = item.json.metadata ?? {};
  let doc = null;
  let fileHash = null;
  try { doc = $('Siapkan Dokumen').itemMatching(i).json; } catch (e) {}
  try { fileHash = $('Hitung Hash File').itemMatching(i).json.file_hash; } catch (e) {}
  const sourceUrl = meta.source_url || doc?.pdf_url;
  if (!sourceUrl) {
    throw new Error('source_url hasil upsert Pinecone tidak diketahui; callback admin dibatalkan.');
  }
  if (!groups.has(sourceUrl)) {
    groups.set(sourceUrl, { doc: doc ?? {}, fileHash: meta.file_hash || fileHash || null, chunks: 0, pasal: new Set() });
  }
  const g = groups.get(sourceUrl);
  g.chunks += 1;
  if (meta.legal_reference) g.pasal.add(meta.legal_reference);
});

return [...groups.entries()].map(([sourceUrl, g]) => ({
  json: {
    workflow: 'WF1',
    execution_id: String($execution.id),
    status: 'success',
    source_url: sourceUrl,
    document_type: g.doc.document_type ?? null,
    document_number: g.doc.document_number ?? null,
    title: g.doc.title ?? null,
    year: g.doc.year ?? null,
    file_hash: g.fileHash,
    namespace: 'kpu_jdih',
    chunks_count: g.chunks,
    pasal_count: g.pasal.size || null,
    pinecone_confirmed: true,
    retry_error_id: g.doc.retry_error_id ?? null,
  },
}));

// Node Crypto (Hitung Hash File) tidak meneruskan file binary.
// Ambil kembali file PDF dari "Download PDF" untuk item yang sama.
return $input.all().map((item, index) => {
  const source = $('Download PDF').itemMatching(index);
  if (!source || !source.binary || !source.binary.data) {
    throw new Error('File PDF hasil download tidak ditemukan untuk ' + (item.json.pdf_url || 'item ' + index));
  }
  return { json: item.json, binary: source.binary, pairedItem: { item: index } };
});

// JDIH menyimpan pilihan wilayah (Kabupaten Subang) di cookie sesi.
const headers = $input.first().json.headers || {};
let setCookie = headers['set-cookie'] || [];
if (!Array.isArray(setCookie)) setCookie = [setCookie];
const cookie = setCookie.map((c) => String(c).split(';')[0]).filter(Boolean).join('; ');
if (!cookie) throw new Error('Cookie sesi JDIH untuk koleksi Kabupaten Subang tidak diterima.');
// Halaman 1-5 memuat keputusan terbaru; dokumen lama sudah tercatat di database.
return [1, 2, 3, 4, 5].map((page) => ({ json: { page, cookie,
  url: `https://jdih.kpu.go.id/kepkpukabkot?page_kepkpukabkot=${page}` } }));

const seen = new Set();
const out = [];
$input.all().forEach((item, i) => {
  const cookie = $('Halaman Daftar KPU Subang').itemMatching(i).json.cookie;
  for (const m of String(item.json.html || '').matchAll(/href="(https:\/\/jdih\.kpu\.go\.id\/kepkpukabkot\/detail\/[^"]+)"/g)) {
    if (seen.has(m[1])) continue;
    seen.add(m[1]);
    out.push({ json: { detail_url: m[1], cookie, source: 'JDIH KPU Kabupaten Subang' } });
  }
});
return out;

// PDF hasil scan tidak punya lapisan teks: tandai agar ditranskripsi LLM.
return $input.all().map((item, i) => {
  // Bila Extract PDF gagal membaca struktur PDF, item berisi error: perlakukan seperti PDF scan (dibaca LLM).
  const text = item.json.error ? '' : String(item.json.text || '');
  const pages = Number(item.json.numpages) || 1;
  // Watermark "jdih.kpu.go.id/jabar/subang" bukan isi dokumen.
  const needs_llm = text.replace(/jdih\.kpu\.go\.id\/\S*/g, '').replace(/\s+/g, '').length < 150 * pages;
  const binary = $('Gabungkan File & Hash').itemMatching(i).binary;
  return { json: { text, numpages: pages, needs_llm }, binary, pairedItem: { item: i } };
});

const PROMPT = "Anda adalah transkriptor dokumen hukum Indonesia, BUKAN peringkas. Baca seluruh isi PDF terlampir berdasarkan gambar halaman dan kembalikan HANYA Markdown isi dokumen, dalam urutan baca yang benar. Tulis penanda <!-- PAGE: N --> di awal setiap halaman. Pertahankan setiap kata, nomor, tanggal, Pasal, ayat, huruf, diktum (KESATU, KEDUA, dst), judul, dan catatan kaki. Jangan menyimpulkan, menerjemahkan, mengoreksi, atau mengarang teks. Untuk teks kurang jelas tulis [TIDAK TERBACA]. Untuk tabel gunakan tabel Markdown tanpa menghilangkan baris. Tulis setiap diktum di baris baru diawali labelnya, mis. 'KESATU : ...'. Abaikan tanda tangan, stempel, dan gambar.";
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: { request: {
    model: 'gpt-6-luna', store: false, reasoning: { effort: 'low' }, max_output_tokens: 32000,
    instructions: PROMPT,
    input: [{ role: 'user', content: [
      { type: 'input_file', filename: 'dokumen.pdf', file_data: 'data:application/pdf;base64,' + buffer.toString('base64') },
      { type: 'input_text', text: 'Transkripsikan seluruh dokumen ini secara lengkap ke Markdown.' },
    ] }],
  } }, pairedItem: { item: i } });
}
return out;

return $input.all().map((item, i) => {
  const parts = [];
  for (const out of item.json.output || []) {
    for (const c of out.content || []) if (c.type === 'output_text' && c.text) parts.push(c.text);
  }
  const text = parts.join('\n').trim();
  if (text.replace(/<!-- PAGE: \d+ -->/g, '').trim().length < 100) {
    throw new Error('Transkripsi LLM kosong untuk ' + $('Siapkan Dokumen').itemMatching(i).json.pdf_url);
  }
  return { json: { text, transcribed_by_llm: true, incomplete: item.json.status === 'incomplete' }, pairedItem: { item: i } };
});

// Satu Pasal atau satu diktum = satu chunk. Pasal sangat panjang dipecah per paragraf.
const DIKTUM = 'KESATU|KEDUA|KETIGA|KEEMPAT|KELIMA|KEENAM|KETUJUH|KEDELAPAN|KESEMBILAN|KESEPULUH|KESEBELAS|KEDUA BELAS|KETIGA BELAS|KEEMPAT BELAS|KELIMA BELAS';
const HEADING = new RegExp('^[\\s#*>|]*(Pasal\\s+\\d+[A-Z]?\\s*\\**\\s*$|(?:' + DIKTUM + ')\\s*\\**\\s*:)', 'i');
const MAX = 3500;
const out = [];
$input.all().forEach((item, i) => {
  const lines = String(item.json.text || '').split('\n');
  const units = [];
  let cur = { ref: '', lines: [] };
  for (const line of lines) {
    const m = line.match(HEADING);
    if (m && cur.lines.join('').trim()) { units.push(cur); cur = { ref: '', lines: [] }; }
    if (m) cur.ref = m[1].replace(/[*:\s]+$/g, '').replace(/\s+/g, ' ').trim();
    cur.lines.push(line);
  }
  if (cur.lines.join('').trim()) units.push(cur);
  for (const u of units) {
    let text = u.lines.join('\n').trim();
    const pieces = [];
    while (text.length > MAX) {
      let cut = text.lastIndexOf('\n\n', MAX);
      if (cut < MAX / 2) cut = text.lastIndexOf('\n', MAX);
      if (cut < MAX / 2) cut = MAX;
      pieces.push(text.slice(0, cut).trim());
      text = text.slice(cut).trim();
    }
    if (text) pieces.push(text);
    for (const p of pieces) {
      if (p.replace(/<!-- PAGE: \d+ -->/g, '').trim().length < 20) continue;
      out.push({ json: { text: p, legal_reference: u.ref, text_source: item.json.transcribed_by_llm ? 'llm_markdown' : 'pdf_text' },
                 pairedItem: { item: i } });
    }
  }
});
return out;
